/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: TypeaheadOutcome, TypeaheadOption, SearchTypeaheadProps
 *   Functions: SearchTypeahead
 * Internal
 *   Types: SuggestionIcon, Suggestion
 *   Functions: optionId
 *   Constants: icons, limits
 * @end-catalog */

import { keepPreviousData, useQuery } from '@tanstack/react-query';
import { Building2, History, Search } from 'lucide-react';
import { useEffect, useLayoutEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router';

import { contentByline, type ListenerSearch } from '../../api/contentSchemas';
import { listenerSearchQuery } from '../../api/listener';
import { Artwork, type ArtworkKind } from '../../components/Artwork';
import { useLocalization } from '../../localization/LocalizationProvider';
import { launchStandalonePlayback } from '../playback/launchPlayback';
import { readSearchHistory, searchHistoryChangedEvent } from './searchHistory';
import { useSearchHistoryRecorder } from './useSearchHistoryRecorder';
import styles from './SearchTypeahead.module.css';

/** Whether a chosen suggestion opened a route or started playback in place. */
export type TypeaheadOutcome = 'navigated' | 'played';

/** One selectable suggestion as the combobox owner sees it. */
export interface TypeaheadOption {
  /** Stable identity across result refreshes, so a highlight never retargets silently. */
  key: string;
  /** DOM id for aria-activedescendant, derived from the key. */
  id: string;
  activate: () => void;
}

export interface SearchTypeaheadProps {
  /** Debounced, normalized draft; empty shows recent searches. */
  query: string;
  listboxId: string;
  activeKey: string | null;
  onActiveKeyChange: (key: string | null) => void;
  onOptionsChange: (options: TypeaheadOption[]) => void;
  /** Called after a suggestion opened a route or started playback. */
  onDone: (outcome: TypeaheadOutcome) => void;
}

type SuggestionIcon = 'search' | 'history' | 'organization';

interface Suggestion {
  key: string;
  title: string;
  subtitle: string;
  artwork?: { src: string; kind: ArtworkKind };
  icon?: SuggestionIcon;
  outcome: TypeaheadOutcome;
  run: () => void;
}

const icons = { search: Search, history: History, organization: Building2 };

// Bounded per group so the panel stays a quick preview; the Search route shows everything.
const limits = { artists: 2, albums: 3, audioTracks: 3, organizations: 1 };

/** Turns a suggestion key into a valid, collision-free DOM id fragment. */
const optionId = (listboxId: string, key: string, index: number) => (
  key.startsWith('history:')
    ? `${listboxId}-history-${index}`
    : `${listboxId}-${key.replace(/[^A-Za-z0-9_-]/g, '_')}`
);

/** Inline shell suggestions: recent searches for an empty draft, grouped top results otherwise. */
export default function SearchTypeahead({
  query,
  listboxId,
  activeKey,
  onActiveKeyChange,
  onOptionsChange,
  onDone
}: SearchTypeaheadProps) {
  const { t } = useLocalization();
  const navigate = useNavigate();
  const { historyIsReady, recordSubmittedQuery, viewerId } = useSearchHistoryRecorder();
  const [history, setHistory] = useState<string[]>([]);
  const results = useQuery({ ...listenerSearchQuery(query), placeholderData: keepPreviousData });
  // Rows from the previous query stay hidden until this query's results arrive.
  const data: ListenerSearch | undefined = results.isPlaceholderData ? undefined : results.data;
  const searching = Boolean(query) && (results.isPending || results.isPlaceholderData);

  useEffect(() => {
    if (!historyIsReady) {
      setHistory([]);
      return undefined;
    }
    const refresh = () => setHistory(readSearchHistory(viewerId));
    refresh();
    window.addEventListener(searchHistoryChangedEvent, refresh);
    return () => window.removeEventListener(searchHistoryChangedEvent, refresh);
  }, [historyIsReady, viewerId]);

  const suggestions = useMemo<Suggestion[]>(() => {
    const openSearch = (value: string) => {
      recordSubmittedQuery(value);
      navigate(`/search?q=${encodeURIComponent(value)}`);
    };
    if (!query) {
      // A recent search re-runs that historical query and moves it to the newest position.
      return history.map((value) => ({
        key: `history:${value}`,
        title: value,
        subtitle: t('search.typeahead.recent'),
        icon: 'history',
        outcome: 'navigated',
        run: () => openSearch(value)
      }));
    }
    // Choosing any result is an explicit selection, so the current query joins search history.
    const choose = (action: () => void) => () => {
      recordSubmittedQuery(query);
      action();
    };
    const items: Suggestion[] = [{
      key: 'search',
      title: t('search.typeahead.search_for', { query }),
      subtitle: '',
      icon: 'search',
      outcome: 'navigated',
      run: () => openSearch(query)
    }];
    if (!data) return items;
    for (const artist of data.artists.slice(0, limits.artists)) {
      items.push({
        key: `artist:${artist.id}`,
        title: artist.name.trim() || t('content.title.unknown_artist'),
        subtitle: t('common.label.artist'),
        artwork: { src: artist.artworkUrl, kind: 'artist' },
        outcome: 'navigated',
        run: choose(() => navigate(`/artists/${encodeURIComponent(artist.id)}`))
      });
    }
    for (const album of data.albums.slice(0, limits.albums)) {
      items.push({
        key: `album:${album.id}`,
        title: album.title.trim() || t('content.title.untitled_album'),
        subtitle: [t('common.label.album'), contentByline(album)].filter(Boolean).join(' · '),
        artwork: { src: album.artworkUrl, kind: 'album' },
        outcome: 'navigated',
        run: choose(() => navigate(`/albums/${encodeURIComponent(album.id)}`))
      });
    }
    for (const track of data.audioTracks.slice(0, limits.audioTracks)) {
      items.push({
        key: `track:${track.id}`,
        title: track.title.trim() || t('content.title.untitled_track'),
        subtitle: [t('common.label.mediatrack'), contentByline(track)].filter(Boolean).join(' · '),
        artwork: { src: track.artworkUrl, kind: 'audioTrack' },
        outcome: 'played',
        run: choose(() => { void launchStandalonePlayback(track, viewerId); })
      });
    }
    for (const organization of data.organizations.slice(0, limits.organizations)) {
      items.push({
        key: `organization:${organization.id}`,
        title: organization.name.trim() || t('content.title.unknown_organization'),
        subtitle: organization.organizationType || t('common.label.organization'),
        icon: 'organization',
        outcome: 'navigated',
        run: choose(() => navigate(`/organizations/${encodeURIComponent(organization.id)}`))
      });
    }
    return items;
  }, [data, history, navigate, query, recordSubmittedQuery, t, viewerId]);

  const options = useMemo<TypeaheadOption[]>(() => suggestions.map((suggestion, index) => ({
    key: suggestion.key,
    id: optionId(listboxId, suggestion.key, index),
    activate: () => {
      suggestion.run();
      onDone(suggestion.outcome);
    }
  })), [listboxId, onDone, suggestions]);

  // Layout effects keep the combobox's aria-expanded and active option in the same commit as the list.
  useLayoutEffect(() => {
    onOptionsChange(options);
  }, [onOptionsChange, options]);
  useLayoutEffect(() => () => onOptionsChange([]), [onOptionsChange]);

  const activeId = options.find((option) => option.key === activeKey)?.id;
  useLayoutEffect(() => {
    // Keyboard highlights inside the scrolling list must stay visible.
    if (activeId) document.getElementById(activeId)?.scrollIntoView?.({ block: 'nearest' });
  }, [activeId]);

  const resultCount = suggestions.length - (query ? 1 : 0);
  const status = !query
    ? ''
    : results.isError && !data
      ? t('search.error')
      : searching
        ? t('search.searching')
        : resultCount === 0
          ? t('search.no_results')
          : '';

  if (suggestions.length === 0 && !status) return null;

  return (
    // Pointer presses inside the panel keep focus in the field, which owns the combobox.
    <div className={styles.panel} onMouseDown={(event) => event.preventDefault()}>
      <p aria-hidden="true" className={styles.hints}>
        <kbd>↑</kbd><kbd>↓</kbd><span>{t('search.typeahead.hint_navigate')}</span>
        <kbd>Enter</kbd><span>{t('search.typeahead.hint_submit')}</span>
      </p>
      {suggestions.length > 0 && (
        <ul
          aria-label={t('search.typeahead.label')}
          className={styles.listbox}
          id={listboxId}
          onMouseLeave={() => onActiveKeyChange(null)}
          role="listbox"
          // The listbox scrolls, but focus stays in the combobox, so it is not a Tab stop.
          tabIndex={-1}
        >
          {suggestions.map((suggestion, index) => {
            const IconGlyph = suggestion.icon ? icons[suggestion.icon] : null;
            const option = options[index];
            return (
              <li
                aria-selected={suggestion.key === activeKey}
                className={styles.option}
                id={option?.id}
                key={suggestion.key}
                onClick={() => option?.activate()}
                onMouseMove={() => {
                  if (suggestion.key !== activeKey) onActiveKeyChange(suggestion.key);
                }}
                role="option"
              >
                <span className={styles.thumb} aria-hidden="true">
                  {suggestion.artwork ? (
                    <Artwork alt="" kind={suggestion.artwork.kind} sizes="3rem" src={suggestion.artwork.src} />
                  ) : IconGlyph ? <IconGlyph focusable="false" strokeWidth={1.8} /> : null}
                </span>
                <span className={styles.copy}>
                  <span className={styles.title}>{suggestion.title}</span>
                  {suggestion.subtitle && <span className={styles.subtitle}>{suggestion.subtitle}</span>}
                </span>
              </li>
            );
          })}
        </ul>
      )}
      {status && <p className={styles.status}>{status}</p>}
      <p className="visually-hidden" role="status">
        {query && !searching && resultCount > 0 ? t('search.typeahead.result_count', { count: resultCount }) : status}
      </p>
    </div>
  );
}
